:root {
    --bg-primary: #0f0f0f;
    --bg-secondary: #1a1a1a;
    --bg-tertiary: #2a2a2a;
    --text-primary: #ffffff;
    --text-secondary: #b0b0b0;
    --accent: #d4af37;
    --accent-light: #e8c547;
    --border: #333333;
    --hover: #252525;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
}

/* ============ HEADER ============ */
.header {
    background-color: var(--bg-secondary);
    border-bottom: 1px solid var(--border);
    padding: 1rem 0;
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.8rem;
    font-weight: 700;
    letter-spacing: 2px;
    color: var(--accent);
    text-decoration: none;
}

.nav {
    display: flex;
    gap: 2rem;
    list-style: none;
}

.nav a {
    color: var(--text-primary);
    text-decoration: none;
    font-size: 0.95rem;
    transition: color 0.3s ease;
}

.nav a:hover {
    color: var(--accent);
}

.header-actions {
    display: flex;
    gap: 1.5rem;
    align-items: center;
}

.icon-button {
    background: none;
    border: none;
    color: var(--text-primary);
    cursor: pointer;
    font-size: 1.2rem;
    transition: color 0.3s ease;
}

.icon-button:hover {
    color: var(--accent);
}

/* ============ HERO SECTION ============ */
.hero {
    background: linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%);
    padding: 6rem 2rem;
    text-align: center;
    border-bottom: 1px solid var(--border);
}

.hero-content {
    max-width: 800px;
    margin: 0 auto;
}

.hero h1 {
    font-size: 3.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    letter-spacing: 1px;
}

.hero-accent {
    color: var(--accent);
}

.hero p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.btn {
    display: inline-block;
    padding: 0.875rem 2.5rem;
    background-color: var(--accent);
    color: var(--bg-primary);
    text-decoration: none;
    font-weight: 600;
    border: none;
    cursor: pointer;
    transition: all 0.3s ease;
    font-size: 1rem;
}

.btn:hover {
    background-color: var(--accent-light);
    transform: translateY(-2px);
}

.btn-secondary {
    background-color: transparent;
    color: var(--accent);
    border: 2px solid var(--accent);
}

.btn-secondary:hover {
    background-color: var(--accent);
    color: var(--bg-primary);
}

/* ============ FEATURED PRODUCTS ============ */
.section {
    max-width: 1400px;
    margin: 0 auto;
    padding: 4rem 2rem;
    border-bottom: 1px solid var(--border);
}

.section-title {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    letter-spacing: 0.5px;
}

.section-subtitle {
    color: var(--text-secondary);
    margin-bottom: 3rem;
    font-size: 1.1rem;
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border);
    overflow: hidden;
    transition: all 0.3s ease;
    cursor: pointer;
}

.product-card:hover {
    border-color: var(--accent);
    transform: translateY(-8px);
    box-shadow: 0 12px 24px rgba(212, 175, 55, 0.15);
}

.product-image {
    width: 100%;
    height: 280px;
    background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    overflow: hidden;
    position: relative;
}

.product-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: var(--accent);
    color: var(--bg-primary);
    padding: 0.5rem 1rem;
    font-weight: 600;
    font-size: 0.85rem;
}

.product-info {
    padding: 1.5rem;
}

.product-category {
    color: var(--text-secondary);
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 0.5rem;
}

.product-name {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.product-description {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin-bottom: 1rem;
    min-height: 2rem;
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.product-price {
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--accent);
}

.product-price .original {
    color: var(--text-secondary);
    text-decoration: line-through;
    font-size: 0.95rem;
    margin-right: 0.5rem;
}

/* ============ DEALS SECTION ============ */
.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.deal-card {
    background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--bg-secondary) 100%);
    border: 1px solid var(--accent);
    padding: 2.5rem;
    position: relative;
    overflow: hidden;
    transition: all 0.3s ease;
}

.deal-card::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -50%;
    width: 200px;
    height: 200px;
    background-color: var(--accent);
    opacity: 0.05;
    border-radius: 50%;
}

.deal-card:hover {
    box-shadow: 0 12px 24px rgba(212, 175, 55, 0.2);
    transform: translateY(-5px);
}

.deal-badge {
    display: inline-block;
    background-color: var(--accent);
    color: var(--bg-primary);
    padding: 0.5rem 1.5rem;
    font-weight: 700;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

.deal-title {
    font-size: 1.8rem;
    font-weight: 700;
    margin-bottom: 0.75rem;
}

.deal-description {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    font-size: 0.95rem;
}

.countdown {
    background-color: var(--bg-primary);
    padding: 1rem;
    border-radius: 4px;
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
    text-align: center;
    color: var(--accent);
    font-weight: 600;
}

/* ============ EDITORIAL SECTION ============ */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border);
    overflow: hidden;
    transition: all 0.3s ease;
}

.editorial-card:hover {
    border-color: var(--accent);
    box-shadow: 0 12px 24px rgba(212, 175, 55, 0.1);
}

.editorial-image {
    width: 100%;
    height: 200px;
    background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    font-style: italic;
    color: var(--text-secondary);
}

.editorial-content {
    padding: 1.75rem;
}

.editorial-date {
    color: var(--text-secondary);
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.editorial-title {
    font-size: 1.2rem;
    font-weight: 600;
    margin-bottom: 0.75rem;
    line-height: 1.4;
}

.editorial-excerpt {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

.read-more {
    color: var(--accent);
    text-decoration: none;
    font-weight: 600;
    transition: color 0.3s ease;
    font-size: 0.95rem;
}

.read-more:hover {
    color: var(--accent-light);
}

/* ============ FOOTER ============ */
.footer {
    background-color: var(--bg-secondary);
    border-top: 1px solid var(--border);
    padding: 3rem 2rem 2rem;
}

.footer-content {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-section h3 {
    margin-bottom: 1rem;
    color: var(--accent);
    font-size: 1rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: 0.75rem;
}

.footer-section a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.3s ease;
    font-size: 0.9rem;
}

.footer-section a:hover {
    color: var(--accent);
}

.footer-bottom {
    border-top: 1px solid var(--border);
    padding-top: 2rem;
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* ============ RESPONSIVE ============ */
@media (max-width: 768px) {
    .nav {
        gap: 1rem;
    }

    .hero h1 {
        font-size: 2.5rem;
    }

    .hero p {
        font-size: 1rem;
    }

    .section-title {
        font-size: 2rem;
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 480px) {
    .header-content {
        flex-direction: column;
        gap: 1rem;
    }

    .nav {
        flex-direction: column;
        gap: 0.5rem;
        text-align: center;
    }

    .hero {
        padding: 3rem 1rem;
    }

    .hero h1 {
        font-size: 2rem;
    }

    .section {
        padding: 2rem 1rem;
    }

    .btn {
        padding: 0.75rem 2rem;
        font-size: 0.9rem;
    }
}
