// React-style component pattern for vanilla JS

// ============ COMPONENT: Header ============
function Header() {
    return `
        <header class="header">
            <div class="header-content">
                <a href="#" class="logo">LUXE & CO.</a>
                <nav>
                    <ul class="nav">
                        <li><a href="#products">Shop</a></li>
                        <li><a href="#deals">Deals</a></li>
                        <li><a href="#editorial">Stories</a></li>
                        <li><a href="#footer">About</a></li>
                    </ul>
                </nav>
                <div class="header-actions">
                    <button class="icon-button" title="Search">🔍</button>
                    <button class="icon-button" title="Account">👤</button>
                    <button class="icon-button" title="Cart">🛒</button>
                </div>
            </div>
        </header>
    `;
}

// ============ COMPONENT: Hero ============
function Hero() {
    return `
        <section class="hero">
            <div class="hero-content">
                <h1>Discover <span class="hero-accent">Premium</span> Craftsmanship</h1>
                <p>Curated collections for those who value quality and elegance</p>
                <button class="btn">Shop Collection</button>
            </div>
        </section>
    `;
}

// ============ COMPONENT: Product Card ============
function ProductCard(product) {
    const priceHtml = product.originalPrice
        ? `<span class="original">$${product.originalPrice}</span>$${product.price}`
        : `$${product.price}`;

    const badgeHtml = product.badge
        ? `<div class="product-badge">${product.badge}</div>`
        : '';

    return `
        <div class="product-card" onclick="handleProductClick('${product.id}')">
            <div class="product-image">
                ${badgeHtml}
                ${product.icon}
            </div>
            <div class="product-info">
                <div class="product-category">${product.category}</div>
                <div class="product-name">${product.name}</div>
                <div class="product-description">${product.description}</div>
                <div class="product-footer">
                    <span class="product-price">${priceHtml}</span>
                </div>
            </div>
        </div>
    `;
}

// ============ COMPONENT: Featured Products Section ============
function FeaturedProducts() {
    const products = [
        {
            id: 'p1',
            name: 'Silk Evening Gown',
            category: 'Womenswear',
            description: 'Timeless elegance in luxurious silk',
            price: '349',
            originalPrice: '449',
            badge: 'New',
            icon: '👗'
        },
        {
            id: 'p2',
            name: 'Leather Crossbody',
            category: 'Accessories',
            description: 'Italian leather crafted to perfection',
            price: '229',
            icon: '👜'
        },
        {
            id: 'p3',
            name: 'Premium Sunglasses',
            category: 'Eyewear',
            description: 'UV protection meets style',
            price: '189',
            originalPrice: '249',
            badge: 'Sale',
            icon: '🕶️'
        },
        {
            id: 'p4',
            name: 'Cashmere Sweater',
            category: 'Menswear',
            description: 'Softness redefined in cashmere',
            price: '279',
            icon: '🧥'
        },
    ];

    const productCards = products.map(p => ProductCard(p)).join('');

    return `
        <section id="products" class="section">
            <h2 class="section-title">Featured Collection</h2>
            <p class="section-subtitle">Explore our handpicked selection of premium pieces</p>
            <div class="products-grid">
                ${productCards}
            </div>
        </section>
    `;
}

// ============ COMPONENT: Deal Card ============
function DealCard(deal) {
    return `
        <div class="deal-card">
            <div class="deal-badge">${deal.badge}</div>
            <h3 class="deal-title">${deal.title}</h3>
            <p class="deal-description">${deal.description}</p>
            <div class="countdown">Ends in: ${deal.timeRemaining}</div>
            <button class="btn">Shop Now</button>
        </div>
    `;
}

// ============ COMPONENT: Deals Section ============
function DealsSection() {
    const deals = [
        {
            id: 'd1',
            badge: 'LIMITED TIME',
            title: '40% OFF',
            description: 'Summer collection sale - select items',
            timeRemaining: '2 days 14 hours'
        },
        {
            id: 'd2',
            badge: 'EARLY ACCESS',
            title: 'Fall Preview',
            description: 'Members-only access to new arrivals',
            timeRemaining: '5 days 8 hours'
        },
        {
            id: 'd3',
            badge: 'EXCLUSIVE',
            title: 'Bundle Deals',
            description: 'Mix & match any 3 items - save 25%',
            timeRemaining: '10 days 12 hours'
        },
    ];

    const dealCards = deals.map(d => DealCard(d)).join('');

    return `
        <section id="deals" class="section">
            <h2 class="section-title">Today's Best Deals</h2>
            <p class="section-subtitle">Limited-time offers on our favorite collections</p>
            <div class="deals-grid">
                ${dealCards}
            </div>
        </section>
    `;
}

// ============ COMPONENT: Editorial Card ============
function EditorialCard(article) {
    return `
        <article class="editorial-card">
            <div class="editorial-image">${article.icon}</div>
            <div class="editorial-content">
                <div class="editorial-date">${article.date}</div>
                <h3 class="editorial-title">${article.title}</h3>
                <p class="editorial-excerpt">${article.excerpt}</p>
                <a href="#" class="read-more">Read Story →</a>
            </div>
        </article>
    `;
}

// ============ COMPONENT: Editorial Section ============
function EditorialSection() {
    const articles = [
        {
            id: 'a1',
            date: 'May 3, 2026',
            title: 'The Art of Layering: A Style Guide',
            excerpt: 'Master the essentials of combining textures and colors for effortless sophistication.',
            icon: '✨'
        },
        {
            id: 'a2',
            date: 'May 1, 2026',
            title: 'Sustainable Fashion Choices',
            excerpt: 'How our commitment to ethical production is shaping the future of luxury retail.',
            icon: '🌱'
        },
        {
            id: 'a3',
            date: 'April 28, 2026',
            title: 'Designer Spotlight: Spring Collection',
            excerpt: 'Discover the inspiration behind this season\'s most anticipated designs.',
            icon: '🎨'
        },
    ];

    const cards = articles.map(a => EditorialCard(a)).join('');

    return `
        <section id="editorial" class="section">
            <h2 class="section-title">Editorial Stories</h2>
            <p class="section-subtitle">Fashion insights, style tips, and behind-the-scenes stories</p>
            <div class="editorial-grid">
                ${cards}
            </div>
        </section>
    `;
}

// ============ COMPONENT: Footer ============
function Footer() {
    return `
        <footer id="footer" class="footer">
            <div class="footer-content">
                <div class="footer-section">
                    <h3>Shop</h3>
                    <ul>
                        <li><a href="#">Women</a></li>
                        <li><a href="#">Men</a></li>
                        <li><a href="#">Accessories</a></li>
                        <li><a href="#">Sale</a></li>
                    </ul>
                </div>
                <div class="footer-section">
                    <h3>Customer Care</h3>
                    <ul>
                        <li><a href="#">Contact Us</a></li>
                        <li><a href="#">Shipping Info</a></li>
                        <li><a href="#">Returns</a></li>
                        <li><a href="#">Size Guide</a></li>
                    </ul>
                </div>
                <div class="footer-section">
                    <h3>Company</h3>
                    <ul>
                        <li><a href="#">About Us</a></li>
                        <li><a href="#">Sustainability</a></li>
                        <li><a href="#">Press</a></li>
                        <li><a href="#">Careers</a></li>
                    </ul>
                </div>
                <div class="footer-section">
                    <h3>Follow</h3>
                    <ul>
                        <li><a href="#">Instagram</a></li>
                        <li><a href="#">Facebook</a></li>
                        <li><a href="#">Pinterest</a></li>
                        <li><a href="#">TikTok</a></li>
                    </ul>
                </div>
            </div>
            <div class="footer-bottom">
                <p>&copy; 2026 Luxe & Co. All rights reserved. | <a href="#" style="color: inherit;">Privacy Policy</a> | <a href="#" style="color: inherit;">Terms of Service</a></p>
            </div>
        </footer>
    `;
}

// ============ APP COMPONENT (Root) ============
function App() {
    return `
        ${Header()}
        ${Hero()}
        ${FeaturedProducts()}
        ${DealsSection()}
        ${EditorialSection()}
        ${Footer()}
    `;
}

// ============ EVENT HANDLERS ============
function handleProductClick(productId) {
    console.log(`Product clicked: ${productId}`);
    // In a real app, this would navigate to product detail page
    alert(`Product ${productId} clicked!`);
}

// ============ RENDER TO DOM ============
document.addEventListener('DOMContentLoaded', function() {
    const root = document.getElementById('root');
    root.innerHTML = App();

    // Add smooth scroll behavior
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function(e) {
            e.preventDefault();
            const target = document.querySelector(this.getAttribute('href'));
            if (target) {
                target.scrollIntoView({ behavior: 'smooth' });
            }
        });
    });

    // Add hover effects to buttons
    document.querySelectorAll('.btn').forEach(btn => {
        btn.addEventListener('mouseenter', function() {
            this.style.cursor = 'pointer';
        });
    });

    // Simple cart notification
    document.querySelector('[title="Cart"]').addEventListener('click', function() {
        alert('Shopping cart functionality coming soon!');
    });

    console.log('Luxe & Co. home page loaded successfully!');
});
